@Component({
  selector: 'app-feed',
  templateUrl: './feed.component.html',
  styleUrls: ['./feed.component.scss']
})

export class FeedComponent implements OnInit {

  
  articles: ArticleSummary[] = [];
  loading: boolean = true;
  error: string = '';
  sortOrder: string = 'desc';




  constructor(
    private articleService: ArticleService,
    private router: Router
  ) {}




  ngOnInit(): void {
    this.loadFeed();
  }




  loadFeed(): void {
    this.loading = true;
    this.articleService.getFeed(this.sortOrder).subscribe({
      next: (data) => {
        this.articles = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Erreur lors du chargement du fil d\'actualité';
        this.loading = false;
      }
    });
  }




  changeSort(order: string): void {
    this.sortOrder = order;
    this.loadFeed();
  }




  goToArticle(id: number): void {
    this.router.navigate(['/article', id]);
  }


  

  goToCreateArticle(): void {
    console.log('Navigation vers /article/create');
    this.router.navigate(['/article/create']);
  }
}

import { Injectable } from '@angular/core';
import { CanActivate, Router } from '@angular/router';
import { AuthService } from '../services/auth.service';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {



  constructor(private authService: AuthService, private router: Router) {}



  
  canActivate(): boolean {
    if (this.authService.isAuthenticated()) {
      return true;
    }

    this.router.navigate(['/login']);
    return false;
  }
}

