import { AuthService } from './../../core/services/auth.service';
import { Component, OnInit } from '@angular/core';
import { UserService } from '../../core/services/user.service';
import { UserProfileResponse } from '../../shared/models/user.model';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';
import { SubscriptionService } from 'src/app/core/services/subscription.service';
import { Topic } from 'src/app/shared/models/topic.model';

@Component({
  selector: 'app-profile',
  templateUrl: './profile.component.html',
  styleUrls: ['./profile.component.scss']
})

export class ProfileComponent implements OnInit {


  userProfile!: UserProfileResponse;
  loading: boolean = true;
  error: string = '';
  formattedCreatedAt: string ='';
  success: string= '';



  constructor(
    private userService: UserService,
    private authService: AuthService,
    private router : Router,
    private datePipe: DatePipe,
    private subscriptionService: SubscriptionService
   // private topic: Topic
) {}




  ngOnInit(): void {
    this.loadProfile();
  }



  
  loadProfile(): void {
    this.loading = true;
    this.userService.getProfile().subscribe({
      next: (data) => {
        this.userProfile = data;
        this.loading = false;
        this.formattedCreatedAt = this.datePipe.transform(data.createdAt, 'dd/MM/yyyy') || '';
      },
      error: (err) => {
        this.error = 'Erreur lors du chargement du profil';
        this.loading = false;
      }
    });
  }




  logout(): void{
    this.authService.logout();
    this.router.navigate(['/login']);
  }


  

unsubscribe(topicId: number): void {
    if (!confirm('Voulez-vous vous désabonner de ce thème ?')) {
      return;
    }

    this.subscriptionService.unsubscribe(topicId).subscribe({
      next: () => {
        // Supprimer le thème de la liste des abonnements
        this.userProfile.subscriptions = this.userProfile.subscriptions.filter(
          (topic: Topic) => topic.id !== topicId
        );
        this.success = 'Désabonnement effectué avec succès';
        setTimeout(() => this.success = '', 3000);
      },
      error: (err) => {
        this.error = err.error?.message || 'Erreur lors du désabonnement';
        setTimeout(() => this.error = '', 3000);
      }
    });
  }




}

import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { UserService } from '../../../core/services/user.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-profile-edit',
  templateUrl: './profile-edit.component.html',
  styleUrls: ['./profile-edit.component.scss']
})

export class ProfileEditComponent implements OnInit {


  profileForm: FormGroup;
  loading: boolean = true;
  submitting: boolean = false;
  error: string = '';
  success: string = '';





  constructor(
    private fb: FormBuilder,
    private userService: UserService,
    private authService: AuthService,  
    private router: Router
  ) {
    this.profileForm = this.fb.group({
      username: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(50)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [
        Validators.minLength(8),
        Validators.pattern(/^(?=.*[0-9])(?=.*[a-z])(?=.*[A-Z])(?=.*[@#$%^&+=!])(?=\S+$).{8,}$/)
      ]],
      confirmPassword: ['']
    }, {
      validators: this.passwordMatchValidator
    });
  }






  ngOnInit(): void {
    this.loadProfile();
  }





  passwordMatchValidator(group: FormGroup): { [key: string]: boolean } | null {
    const password = group.get('password')?.value;
    const confirmPassword = group.get('confirmPassword')?.value;
    return password === confirmPassword ? null : { mismatch: true };
  }





  loadProfile(): void {
    this.loading = true;
    this.userService.getProfile().subscribe({
      next: (data) => {
        this.profileForm.patchValue({
          username: data.username,
          email: data.email
        });
        this.loading = false;
      },
      error: () => {
        this.error = 'Erreur lors du chargement du profil';
        this.loading = false;
      }
    });
  }





  onSubmit(): void {
    if (this.profileForm.invalid) {
      return;
    }

    this.submitting = true;
    this.error = '';
    this.success = '';

    const formValue = this.profileForm.value;
    const request: any = {
      username: formValue.username.trim(),
      email: formValue.email.trim()
    };

    if (formValue.password && formValue.password.length >= 8) {
      request.password = formValue.password;
    }

    this.userService.updateProfile(request).subscribe({
      next: (data) => {
        this.success = ' Profil mis à jour avec succès !';
        this.submitting = false;
        
        //  Reconnecter l'utilisateur avec ses nouvelles identifiants
        setTimeout(() => {
          //  Déconnecter
          this.authService.logout();
          
          //  Reconnecter automatiquement
          this.authService.login({
            usernameOrEmail: data.username,
            password: formValue.password || 'ancien_mot_de_passe_non_disponible'
          }).subscribe({
            next: (loginResponse) => {
              this.authService.saveToken(loginResponse.token);
              this.router.navigate(['/profile']).then(() => {
                window.location.reload();
              });
            },
            error: () => {
              // Si la reconnexion échoue (mot de passe non fourni), rediriger vers login
              this.router.navigate(['/login']);
            }
          });
        }, 1500);
      },
      error: (err) => {
        this.error = err.error?.message || 'Erreur lors de la mise à jour du profil';
        this.submitting = false;
      }
    });
  }





  
  cancel(): void {
    this.router.navigate(['/profile']);
  }
}

