import { Component, OnInit } from '@angular/core';
import { TopicService } from '../../core/services/topic.service';
import { SubscriptionService } from '../../core/services/subscription.service';
import { TopicDTO } from '../../shared/models/topic.model';

@Component({
  selector: 'app-topics',
  templateUrl: './topics.component.html',
  styleUrls: ['./topics.component.scss']
})

export class TopicsComponent implements OnInit {


  topics: TopicDTO[] = [];
  loading: boolean = true;
  error: string = '';




  constructor(
    private topicService: TopicService,
    private subscriptionService: SubscriptionService
  ) {}





  ngOnInit(): void {
    this.loadTopics();
  }





  loadTopics(): void {
    this.loading = true;
    this.topicService.getAllTopics().subscribe({
      next: (data) => {
        this.topics = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Erreur lors du chargement des thèmes';
        this.loading = false;
      }
    });
  }





  subscribe(topicId: number): void {
    this.subscriptionService.subscribe(topicId).subscribe({
      next: () => {
        // Mettre à jour le statut local
        const topic = this.topics.find(t => t.id === topicId);
        if (topic) {
          topic.subscribed = true;
        }
      },
      error: (err) => {
        this.error = err.error?.message || 'Erreur lors de l\'abonnement';
      }
    });
  }





  unsubscribe(topicId: number): void {
    this.subscriptionService.unsubscribe(topicId).subscribe({
      next: () => {
        // Mettre à jour le statut local
        const topic = this.topics.find(t => t.id === topicId);
        if (topic) {
          topic.subscribed = false;
        }
      },
      error: (err) => {
        this.error = err.error?.message || 'Erreur lors du désabonnement';
      }
    });
  }




  
  onSubscriptionToggle(topic: TopicDTO): void {
    if (topic.subscribed) {
      this.unsubscribe(topic.id);
    } else {
      this.subscribe(topic.id);
    }
  }
}

import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ArticleService } from '../../../core/services/article.service';
import { ArticleResponse } from '../../../shared/models/article.model';
import { CommentRequest } from '../../../shared/models/comment.model';

@Component({
  selector: 'app-article-detail',
  templateUrl: './article-detail.component.html',
  styleUrls: ['./article-detail.component.scss']
})

export class ArticleDetailComponent implements OnInit {


  article!: ArticleResponse;
  loading: boolean = true;
  error: string = '';
  commentForm: FormGroup;
  submitting: boolean = false;



  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private articleService: ArticleService,
    private fb: FormBuilder
  ) {
    this.commentForm = this.fb.group({
      content: ['', [Validators.required, Validators.minLength(1)]]
    });
  }





  ngOnInit(): void {
    const id = this.route.snapshot.params['id'];
    if (id) {
      this.loadArticle(id);
    }
  }





  loadArticle(id: number): void {
    this.loading = true;
    this.articleService.getArticle(id).subscribe({
      next: (data) => {
        this.article = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Erreur lors du chargement de l\'article';
        this.loading = false;
      }
    });
  }







  onSubmitComment(): void {
    if (this.commentForm.invalid || this.submitting) {
      return;
    }

    this.submitting = true;
    const request: CommentRequest = {
      content: this.commentForm.value.content
    };

    this.articleService.addComment(this.article.id, request).subscribe({
      next: (comment) => {
        if (this.article.comments) {
          this.article.comments.push(comment);
        } else {
          this.article.comments = [comment];
        }
        this.commentForm.reset();
        this.submitting = false;
      },
      error: (err) => {
        this.error = err.error?.message || 'Erreur lors de l\'ajout du commentaire';
        this.submitting = false;
      }
    });
  }





  
  goBack(): void {
    this.router.navigate(['/feed']);
  }
}

